1	package api
2	
3	import (
4		"net/http"
5		"net/url"
6		"strconv"
7		"strings"
8		"unicode/utf8"
9	
10		"github.com/gin-gonic/gin"
11	
12		"github.com/xjeey8iust/sen-audit-ledger/internal/store"
13	)
14	
15	// Bounds for the pagination parameters of GET /events.
16	const (
17		defaultEventPageLimit = 50
18		maxEventPageLimit     = 100
19	)
20	
21	// eventsPageResponse is the GET /events body. NextAfterSeq is a pointer so
22	// JSON renders null when no further records match.
23	type eventsPageResponse struct {
24		Events       []eventResponse `json:"events"`
25		NextAfterSeq *int64          `json:"next_after_seq"`
26	}
27	
28	// getEvents lists stored audit records by account, time window and seq
29	// cursor. Every query parameter is validated before storage is touched, so a
30	// malformed request can never surface as a storage failure.
31	func getEvents(st *store.Store) gin.HandlerFunc {
32		return func(c *gin.Context) {
33			filter, ok := parseEventsQuery(c)
34			if !ok {
35				return
36			}
37			events, err := st.ListEvents(filter)
38			if err != nil {
39				writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "storage is not available")
40				return
41			}
42	
43			page := events
44			var next *int64
45			if int64(len(page)) > filter.Limit {
46				page = page[:filter.Limit]
47				last := page[len(page)-1].Seq
48				next = &last
49			}
50			out := make([]eventResponse, 0, len(page))
51			for _, e := range page {
52				out = append(out, eventResponse{
53					Account:    e.Account,
54					Operation:  e.Operation,
55					Resource:   e.Resource,
56					Result:     e.Result,
57					OccurredAt: e.OccurredAt,
58					Seq:        e.Seq,
59					PrevHash:   e.PrevHash,
60					Hash:       e.Hash,
61				})
62			}
63			c.JSON(http.StatusOK, eventsPageResponse{Events: out, NextAfterSeq: next})
64		}
65	}
66	
67	// parseEventsQuery validates the GET /events query string against the audit
68	// contract. On any violation it writes the invalid_audit_input error and
69	// reports false.
70	func parseEventsQuery(c *gin.Context) (store.EventFilter, bool) {
71		invalid := func() (store.EventFilter, bool) {
72			writeError(c, http.StatusBadRequest, "invalid_audit_input", "query parameters are not valid")
73			return store.EventFilter{}, false
74		}
75	
76		values, err := url.ParseQuery(c.Request.URL.RawQuery)
77		if err != nil {
78			// Bad percent-escapes or stray semicolons: the query string does not
79			// decode cleanly.
80			return invalid()
81		}
82	
83		filter := store.EventFilter{Limit: defaultEventPageLimit}
84		for name, list := range values {
85			if len(list) != 1 {
86				// A repeated parameter is rejected even when the values agree.
87				return invalid()
88			}
89			value := list[0]
90			if value == "" || !utf8.ValidString(value) {
91				// An explicit empty value, or text that did not decode to valid
92				// UTF-8.
93				return invalid()
94			}
95			switch name {
96			case "account":
97				// Matching is exact on the decoded text: case matters and the
98				// surrounding whitespace is kept, but a whitespace-only value
99				// can never name an account.
100				if strings.TrimSpace(value) == "" {
101					return invalid()
102				}
103				filter.Account = &value
104			case "from", "to":
105				normalized, ok := normalizeOccurredAt(value)
106				if !ok {
107					return invalid()
108				}
109				if name == "from" {
110					filter.From = &normalized
111				} else {
112					filter.To = &normalized
113				}
114			case "limit":
115				n, ok := parseUintParam(value)
116				if !ok || n < 1 || n > maxEventPageLimit {
117					return invalid()
118				}
119				filter.Limit = n
120			case "after_seq":
121				n, ok := parseUintParam(value)
122				if !ok {
123					return invalid()
124				}
125				filter.AfterSeq = n
126			default:
127				// Unknown parameters are rejected.
128				return invalid()
129			}
130		}
131	
132		if filter.From != nil && filter.To != nil && store.CompareInstants(*filter.From, *filter.To) >= 0 {
133			// The window is only valid when from is strictly earlier than to.
134			return invalid()
135		}
136		return filter, true
137	}
138	
139	// parseUintParam parses a pagination parameter that only accepts ASCII
140	// decimal digits (leading zeros allowed) and must fit a non-negative int64.
141	func parseUintParam(value string) (int64, bool) {
142		if !isUintLiteral(value) {
143			return 0, false
144		}
145		n, err := strconv.ParseInt(value, 10, 64)
146		if err != nil {
147			return 0, false
148		}
149		return n, true
150	}
