1	package api
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"net/http/httptest"
8		"strings"
9		"testing"
10	)
11	
12	func getEventsQuery(t *testing.T, router http.Handler, rawQuery string) *httptest.ResponseRecorder {
13		t.Helper()
14		recorder := httptest.NewRecorder()
15		target := "/events"
16		if rawQuery != "" {
17			target += "?" + rawQuery
18		}
19		request := httptest.NewRequest(http.MethodGet, target, nil)
20		router.ServeHTTP(recorder, request)
21		return recorder
22	}
23	
24	// mustPost appends one event and returns the decoded 201 body.
25	func mustPost(t *testing.T, router http.Handler, body string) map[string]any {
26		t.Helper()
27		recorder := postEventBody(t, router, body)
28		if recorder.Code != http.StatusCreated {
29			t.Fatalf("seed post: status = %d (%s)", recorder.Code, recorder.Body.String())
30		}
31		return decodeEvent(t, recorder)
32	}
33	
34	// eventBody builds a valid append body for the given account and occurred_at.
35	func eventBody(account, occurredAt string) string {
36		return fmt.Sprintf(`{"account":%q,"operation":"op","resource":"res","result":"ok","occurred_at":%q}`, account, occurredAt)
37	}
38	
39	// decodePage decodes a 200 GET /events body and checks the top-level shape:
40	// exactly the events and next_after_seq keys.
41	func decodePage(t *testing.T, recorder *httptest.ResponseRecorder) (events []map[string]any, next any) {
42		t.Helper()
43		var decoded map[string]any
44		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
45			t.Fatalf("decode page: %v", err)
46		}
47		if len(decoded) != 2 {
48			t.Fatalf("response keys = %v, want only events and next_after_seq", decoded)
49		}
50		rawEvents, ok := decoded["events"].([]any)
51		if !ok {
52			t.Fatalf("events = %v, want an array", decoded["events"])
53		}
54		for _, raw := range rawEvents {
55			event, ok := raw.(map[string]any)
56			if !ok {
57				t.Fatalf("event = %v, want an object", raw)
58			}
59			events = append(events, event)
60		}
61		return events, decoded["next_after_seq"]
62	}
63	
64	// wantSeqs asserts the page carries exactly the given seq values in order.
65	func wantSeqs(t *testing.T, events []map[string]any, seqs ...float64) {
66		t.Helper()
67		if len(events) != len(seqs) {
68			t.Fatalf("page has %d events, want %d (%v)", len(events), len(seqs), events)
69		}
70		for i, seq := range seqs {
71			if events[i]["seq"] != seq {
72				t.Fatalf("event %d seq = %v, want %v", i, events[i]["seq"], seq)
73			}
74		}
75	}
76	
77	// wantInvalidQuery asserts the invalid_audit_input rejection shape for one
78	// GET /events query string.
79	func wantInvalidQuery(t *testing.T, router http.Handler, rawQuery string) {
80		t.Helper()
81		recorder := getEventsQuery(t, router, rawQuery)
82		if recorder.Code != http.StatusBadRequest {
83			t.Fatalf("query %q: status = %d, want 400 (%s)", rawQuery, recorder.Code, recorder.Body.String())
84		}
85		var decoded struct {
86			Error struct {
87				Code    string `json:"code"`
88				Message string `json:"message"`
89			} `json:"error"`
90		}
91		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
92			t.Fatalf("query %q: decode error body: %v", rawQuery, err)
93		}
94		if decoded.Error.Code != "invalid_audit_input" {
95			t.Fatalf("query %q: code = %q", rawQuery, decoded.Error.Code)
96		}
97		if decoded.Error.Message == "" {
98			t.Fatalf("query %q: message must be non-empty", rawQuery)
99		}
100	}
101	
102	func TestGetEventsEmptyLedger(t *testing.T) {
103		router := NewRouter(openTestStore(t))
104	
105		recorder := getEventsQuery(t, router, "")
106		if recorder.Code != http.StatusOK {
107			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
108		}
109		if !strings.Contains(recorder.Body.String(), `"events":[]`) {
110			t.Fatalf("body = %s, want an empty events array", recorder.Body.String())
111		}
112		events, next := decodePage(t, recorder)
113		if len(events) != 0 || next != nil {
114			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
115		}
116	}
117	
118	func TestGetEventsReturnsStoredRecordsInSeqOrder(t *testing.T) {
119		router := NewRouter(openTestStore(t))
120	
121		first := mustPost(t, router, eventBody("  alice  ", "2026-10-05T08:30:00+08:00"))
122		second := mustPost(t, router, eventBody("bob", "2026-10-05T01:00:00.2500Z"))
123	
124		recorder := getEventsQuery(t, router, "")
125		if recorder.Code != http.StatusOK {
126			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
127		}
128		events, next := decodePage(t, recorder)
129		wantSeqs(t, events, 1, 2)
130		if next != nil {
131			t.Fatalf("next_after_seq = %v, want null", next)
132		}
133		// Each item reuses the append response shape and keeps the stored text.
134		for i, posted := range []map[string]any{first, second} {
135			for _, key := range []string{"account", "operation", "resource", "result", "occurred_at", "seq", "prev_hash", "hash"} {
136				if events[i][key] != posted[key] {
137					t.Fatalf("event %d %s = %v, want %v", i, key, events[i][key], posted[key])
138				}
139			}
140			if len(events[i]) != 8 {
141				t.Fatalf("event %d keys = %v, want the 8 append response fields", i, events[i])
142			}
143		}
144		if events[0]["account"] != "  alice  " || events[1]["occurred_at"] != "2026-10-05T01:00:00.2500Z" {
145			t.Fatalf("stored originals not preserved: %v", events)
146		}
147	}
148	
149	func TestGetEventsFiltersByAccountExactly(t *testing.T) {
150		router := NewRouter(openTestStore(t))
151	
152		mustPost(t, router, eventBody("alice", "2026-10-05T00:00:00Z"))
153		mustPost(t, router, eventBody("Alice", "2026-10-05T00:01:00Z"))
154		mustPost(t, router, eventBody(" alice ", "2026-10-05T00:02:00Z"))
155		mustPost(t, router, eventBody("bob", "2026-10-05T00:03:00Z"))
156	
157		// Exact, case-sensitive match on the decoded text.
158		events, _ := decodePage(t, getEventsQuery(t, router, "account=alice"))
159		wantSeqs(t, events, 1)
160		events, _ = decodePage(t, getEventsQuery(t, router, "account=Alice"))
161		wantSeqs(t, events, 2)
162		// Surrounding whitespace is part of the value.
163		events, _ = decodePage(t, getEventsQuery(t, router, "account=%20alice%20"))
164		wantSeqs(t, events, 3)
165		// No match yields an empty page and a null cursor.
166		events, next := decodePage(t, getEventsQuery(t, router, "account=ALICE"))
167		if len(events) != 0 || next != nil {
168			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
169		}
170	}
171	
172	func TestGetEventsRejectsBlankAccount(t *testing.T) {
173		router := NewRouter(openTestStore(t))
174		for _, query := range []string{"account=", "account", "account=%20", "account=%09%20"} {
175			wantInvalidQuery(t, router, query)
176		}
177	}
178	
179	func TestGetEventsTimeWindow(t *testing.T) {
180		router := NewRouter(openTestStore(t))
181	
182		mustPost(t, router, eventBody("a", "2026-10-05T00:00:00Z"))
183		mustPost(t, router, eventBody("a", "2026-10-05T01:00:00.250Z"))
184		mustPost(t, router, eventBody("a", "2026-10-05T02:00:00Z"))
185	
186		// from is inclusive, to is exclusive; ".25" names the same instant as
187		// the stored ".250".
188		events, _ := decodePage(t, getEventsQuery(t, router,
189			"from=2026-10-05T01:00:00.25Z&to=2026-10-05T02:00:00Z"))
190		wantSeqs(t, events, 2)
191	
192		// A bound given with an offset names the same instant as its UTC form.
193		events, _ = decodePage(t, getEventsQuery(t, router,
194			"from=2026-10-05T09:00:00.250%2B08:00&to=2026-10-05T10:00:00%2B08:00"))
195		wantSeqs(t, events, 2)
196	
197		// Only a lower bound, and only an upper bound.
198		events, _ = decodePage(t, getEventsQuery(t, router, "from=2026-10-05T00:30:00Z"))
199		wantSeqs(t, events, 2, 3)
200		events, _ = decodePage(t, getEventsQuery(t, router, "to=2026-10-05T01:00:00.250Z"))
201		wantSeqs(t, events, 1)
202	
203		// A window that matches nothing.
204		events, next := decodePage(t, getEventsQuery(t, router,
205			"from=2026-10-06T00:00:00Z&to=2026-10-07T00:00:00Z"))
206		if len(events) != 0 || next != nil {
207			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
208		}
209	}
210	
211	func TestGetEventsTimeWindowFractionPrecision(t *testing.T) {
212		router := NewRouter(openTestStore(t))
213	
214		// A fraction longer than nanosecond precision is stored verbatim.
215		mustPost(t, router, eventBody("a", "2026-10-05T00:00:00.000000000000001Z"))
216		mustPost(t, router, eventBody("a", "2026-10-05T00:00:00.5Z"))
217	
218		// The record sorts after a bound one tick below it and before one above.
219		events, _ := decodePage(t, getEventsQuery(t, router, "from=2026-10-05T00:00:00.000000000000002Z"))
220		wantSeqs(t, events, 2)
221		events, _ = decodePage(t, getEventsQuery(t, router, "to=2026-10-05T00:00:00.000000000000001Z"))
222		if len(events) != 0 {
223			t.Fatalf("events = %v, want none before the first record's instant", events)
224		}
225		// ".5" includes a record at exactly ".5" as the lower bound…
226		events, _ = decodePage(t, getEventsQuery(t, router, "from=2026-10-05T00:00:00.4999Z&to=2026-10-05T00:00:00.5001Z"))
227		wantSeqs(t, events, 2)
228		// …but ".50" names the same instant and excludes it as the upper bound.
229		events, _ = decodePage(t, getEventsQuery(t, router, "from=2026-10-05T00:00:00.4999Z&to=2026-10-05T00:00:00.50Z"))
230		if len(events) != 0 {
231			t.Fatalf("events = %v, want the record at .5 excluded by the equal upper bound", events)
232		}
233	}
234	
235	func TestGetEventsRejectsInvalidTimeBounds(t *testing.T) {
236		router := NewRouter(openTestStore(t))
237		cases := []string{
238			"from=notatime",
239			"from=2026-10-05T00:00:00",                                 // no zone
240			"from=2026-13-01T00:00:00Z",                                // bad month
241			"from=2016-12-31T23:59:60Z",                                // leap second
242			"from=0000-01-01T00:00:00%2B00:01",                         // UTC year below 0000
243			"to=9999-12-31T23:59:59.5-00:01",                           // UTC year above 9999
244			"from=",                                                    // explicit empty
245			"to=2026-10-05T00:00:00Z&from=2026-10-05T00:00:01Z",        // from after to
246			"from=2026-10-05T00:00:00Z&to=2026-10-05T00:00:00Z",        // from equal to to
247			"from=2026-10-05T08:00:00%2B08:00&to=2026-10-05T00:00:00Z", // same instant, different spelling
248			"from=2026-10-05T00:00:00.5Z&to=2026-10-05T00:00:00.50Z",   // same instant, different fraction
249		}
250		for _, query := range cases {
251			wantInvalidQuery(t, router, query)
252		}
253	}
254	
255	func TestGetEventsPagination(t *testing.T) {
256		router := NewRouter(openTestStore(t))
257		for i := 0; i < 5; i++ {
258			mustPost(t, router, eventBody("a", fmt.Sprintf("2026-10-05T00:0%d:00Z", i)))
259		}
260	
261		// First page: limit records and a cursor pointing at the last one.
262		events, next := decodePage(t, getEventsQuery(t, router, "limit=2"))
263		wantSeqs(t, events, 1, 2)
264		if next != float64(2) {
265			t.Fatalf("next_after_seq = %v, want 2", next)
266		}
267	
268		// Second page continues strictly after the cursor.
269		events, next = decodePage(t, getEventsQuery(t, router, "limit=2&after_seq=2"))
270		wantSeqs(t, events, 3, 4)
271		if next != float64(4) {
272			t.Fatalf("next_after_seq = %v, want 4", next)
273		}
274	
275		// Last page is short and closes the cursor.
276		events, next = decodePage(t, getEventsQuery(t, router, "limit=2&after_seq=4"))
277		wantSeqs(t, events, 5)
278		if next != nil {
279			t.Fatalf("next_after_seq = %v, want null", next)
280		}
281	
282		// A cursor past the end yields an empty page and a null cursor.
283		events, next = decodePage(t, getEventsQuery(t, router, "after_seq=99"))
284		if len(events) != 0 || next != nil {
285			t.Fatalf("events = %v next = %v, want empty page and null cursor", events, next)
286		}
287	
288		// Leading zeros are accepted; the maximum int64 cursor is valid.
