}

// isUintLiteral reports whether the raw JSON value is a non-negative integer
// literal with no fraction, exponent or sign.
func isUintLiteral(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
